// Fetch helper. The default views are served from pre-computed static JSON (CDN, no serverless cold start);
// everything else goes to the live API under /api. Pre-computed files are generated by scripts/export_precomputed.py
// and a backend test checks they equal the API output and that the constants below match the backend defaults.
const DEFAULT_COVERAGE = 0.8;
const DEFAULT_BAND_BASIS = "prior";
const DEFAULT_BASIS = "decision";
const DEFAULT_COST_RATIO = 3;
const DEFAULT_MARGIN_BY = "flat";

const isSet = (v) => v !== "" && v != null;

function precomputedUrl(path, params) {
  const p = Object.fromEntries(Object.entries(params).filter(([, v]) => isSet(v)));
  if (path === "meta") return "/precomputed/meta.json";
  if (path === "accuracy") {
    if (p.basis === DEFAULT_BASIS) delete p.basis;
    return Object.keys(p).length === 0 ? "/precomputed/accuracy.json" : null;
  }
  if (path === "recent-bias") return Object.keys(p).length === 0 ? "/precomputed/recent_bias.json" : null;
  if (path === "cutoff-compare") return "/precomputed/cutoff_compare.json";
  if (path === "replay") {
    if (Number(p.cost_ratio) === DEFAULT_COST_RATIO) delete p.cost_ratio;
    if (p.margin_by === DEFAULT_MARGIN_BY) delete p.margin_by;
    return Object.keys(p).length === 0 ? "/precomputed/replay.json" : null;
  }
  if (path === "tradeoff") {
    if (Number(p.cost_ratio) === DEFAULT_COST_RATIO) delete p.cost_ratio;
    if (p.margin_by === DEFAULT_MARGIN_BY) delete p.margin_by;
    return Object.keys(p).length === 0 ? "/precomputed/tradeoff.json" : null;
  }
  if (path === "baseline") return Object.keys(p).length === 0 ? "/precomputed/baseline.json" : null;
  if (path === "margin-check") {
    if (Number(p.cost_ratio) === DEFAULT_COST_RATIO) delete p.cost_ratio;
    if (p.margin_by === DEFAULT_MARGIN_BY) delete p.margin_by;
    return Object.keys(p).length === 0 ? "/precomputed/margin_check.json" : null;
  }
  if (path === "decision") {
    if (Number(p.coverage) === DEFAULT_COVERAGE) delete p.coverage;
    if (p.band_basis === DEFAULT_BAND_BASIS) delete p.band_basis;
    if (Number(p.cost_ratio) === DEFAULT_COST_RATIO) delete p.cost_ratio;
    if (p.margin_by === DEFAULT_MARGIN_BY) delete p.margin_by;
    const { day, ...rest } = p;
    return day && Object.keys(rest).length === 0 && /^\d{4}-\d{2}-\d{2}$/.test(day) ? `/precomputed/decision/${day}.json` : null;
  }
  return null;
}

async function tryStatic(url) {
  try {
    const res = await fetch(url);
    // A host may answer unknown paths with index.html (200); only accept real JSON.
    if (res.ok && (res.headers.get("content-type") || "").includes("json")) return await res.json();
  } catch { /* fall through to the live API */ }
  return null;
}

export async function api(path, params = {}) {
  const url = precomputedUrl(path, params);
  if (url) {
    const hit = await tryStatic(url);
    if (hit) return hit;
  }
  const qs = new URLSearchParams(Object.entries(params).filter(([, v]) => isSet(v))).toString();
  const res = await fetch(`/api/${path}${qs ? `?${qs}` : ""}`);
  if (!res.ok) throw new Error(`${res.status} ${(await res.text()).slice(0, 200)}`);
  return res.json();
}

/** Wake the serverless function in the background so the first non-default request is not a cold start. */
export function warmApi() {
  const go = () => fetch(`/api/warm?ts=${Date.now()}`).catch(() => {});
  if ("requestIdleCallback" in window) requestIdleCallback(go, { timeout: 3000 });
  else setTimeout(go, 1500);
}
